/* INS owner/manager learning course. Offline lessons; optional configured certificate email. */
'use strict';
const COURSE=DATA.modules, ASSETS=DATA.assets, REFERENCES=DATA.references, KEY='ins-operations-manual-training-2026-v3', EARLIER_KEY='ins-operations-manual-training-2026-v2', LEGACY_KEY='ins-owner-training-2026-v1';
const COURSE_EDITION=DATA.course.edition,TOTAL_QUESTIONS=DATA.course.totalQuestions,PLANNED_MINUTES=DATA.course.plannedMinutes,DURATION_LABEL=DATA.course.durationLabel;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mod=id=>COURSE.find(m=>m.id===Number(id));
const blankModule=()=>({read:[],activities:{},lab:false,labValues:{},reflection:'',draft:{},attempts:[]});
const makeOptionSeed=()=>Array.from(crypto.getRandomValues(new Uint32Array(4)),x=>x.toString(16).padStart(8,'0')).join('');
const blank=()=>({version:1,courseEdition:COURSE_EDITION,optionSeed:makeOptionSeed(),earlierEdition:null,name:'',email:'',store:'',storeName:'',storeNumber:'',certificate:null,signOn:null,seconds:0,paused:false,last:null,completedAt:null,modules:Object.fromEntries(COURSE.map(m=>[m.id,blankModule()]))});
function optionIndexes(options,key){const order=options.map((_,i)=>i),seed=state.optionSeed+':'+key;let h=2166136261;for(let i=0;i<seed.length;i++)h=Math.imul(h^seed.charCodeAt(i),16777619);for(let i=order.length-1;i>0;i--){h^=h<<13;h^=h>>>17;h^=h<<5;const j=Math.floor((h>>>0)/4294967296*(i+1));[order[i],order[j]]=[order[j],order[i]];}return order;}
let storageOK=true,state;
function normalize(raw){
 if(!raw||raw.version!==1||typeof raw.modules!=='object'||!raw.modules)throw Error('This is not a compatible INS progress file.');
 let v=blank(),upgrading=raw.courseEdition!==COURSE_EDITION;v.name=String(raw.name||'').slice(0,120);v.email=String(raw.email||'').trim().slice(0,254);v.storeName=String(raw.storeName||raw.store||'').trim().slice(0,120);v.store=v.storeName;v.storeNumber=String(raw.storeNumber||'').trim().slice(0,40);
 if(/^[a-f0-9]{32}$/.test(raw.optionSeed||''))v.optionSeed=raw.optionSeed;
 const earlier=upgrading?raw:raw.earlierEdition;if(earlier&&earlier.version===1&&earlier.modules&&typeof earlier.modules==='object'&&(earlier.name||Object.values(earlier.modules).some(m=>m?.read?.length))){const copy={...earlier};delete copy.earlierEdition;const encoded=JSON.stringify(copy);if(encoded.length<=1500000)v.earlierEdition=JSON.parse(encoded);}
 if(!upgrading&&raw.certificate&&/^[a-f0-9]{64}$/.test(raw.certificate.fingerprint||'')&&/^INS-\d{8}-[A-F0-9]{12}$/.test(raw.certificate.id||'')&&['ready','sending','submitted','failed','uncertain'].includes(raw.certificate.status)){const c=raw.certificate;v.certificate={fingerprint:c.fingerprint,id:c.id,status:c.status,attemptedAt:typeof c.attemptedAt==='string'&&!isNaN(Date.parse(c.attemptedAt))?c.attemptedAt:null,submittedAt:typeof c.submittedAt==='string'&&!isNaN(Date.parse(c.submittedAt))?c.submittedAt:null,...(typeof c.messageId==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(c.messageId)?{messageId:c.messageId}:{})};}
 if(!upgrading)v.signOn=normalizeSignOn(raw.signOn);
 v.seconds=Number.isFinite(raw.seconds)?Math.max(0,Math.min(raw.seconds,3600000)):0;v.paused=!!raw.paused;v.completedAt=!upgrading&&typeof raw.completedAt==='string'&&!isNaN(Date.parse(raw.completedAt))?raw.completedAt:null;
 v.last=typeof raw.last==='string'&&/^#\/(module|read|practice|quiz)\/\d+(\/\d+)?$/.test(raw.last)?raw.last:null;
 COURSE.forEach(m=>{let r=raw.modules[m.id]||{},x=v.modules[m.id];x.read=Array.isArray(r.read)?[...new Set(r.read.filter(n=>Number.isInteger(n)&&n>=0&&n<m.lessons.length))]:[];
  m.activities.forEach((a,i)=>{let z=r.activities?.[i];if(z&&Number.isInteger(z.choice)&&z.choice>=0&&z.choice<a.options.length)x.activities[i]={choice:z.choice,done:!!z.done};});
  x.lab=!!r.lab;x.labValues=r.labValues&&typeof r.labValues==='object'?Object.fromEntries(Object.entries(r.labValues).filter(([k,z])=>/^[a-z0-9_-]{1,30}$/i.test(k)&&(typeof z==='string'||typeof z==='boolean')).map(([k,z])=>[k,typeof z==='string'?z.slice(0,200):z])):{};
  x.reflection=String(r.reflection||'').slice(0,3000);
  m.questions.forEach((q,i)=>{let n=r.draft?.[i];if((!upgrading||m.retainedQuestionIndexes?.includes(i))&&Number.isInteger(n)&&n>=0&&n<q.options.length)x.draft[i]=n;});
  if(upgrading&&Array.isArray(r.attempts)&&r.attempts.length){const earlierAnswers=r.attempts.at(-1)?.answers;if(Array.isArray(earlierAnswers))earlierAnswers.forEach((n,i)=>{if(i<m.questions.length&&m.retainedQuestionIndexes?.includes(i)&&Number.isInteger(n)&&n>=0&&n<m.questions[i].options.length)x.draft[i]=n;});}
  x.attempts=Array.isArray(r.attempts)?r.attempts.slice(-100).filter(a=>Array.isArray(a.answers)&&a.answers.length===m.questions.length&&a.answers.every((n,i)=>Number.isInteger(n)&&n>=0&&n<m.questions[i].options.length)).map(a=>{let score=a.answers.reduce((s,n,i)=>s+(n===m.questions[i].answer),0);return {answers:a.answers,score,total:m.questions.length,date:typeof a.date==='string'&&!isNaN(Date.parse(a.date))?a.date:new Date().toISOString()};}):[];
  x.retake=!!r.retake;
 });return v;
}
try{let raw=localStorage.getItem(KEY),earlier=raw?null:(localStorage.getItem(EARLIER_KEY)||localStorage.getItem(LEGACY_KEY));state=raw?normalize(JSON.parse(raw)):earlier?normalize(JSON.parse(earlier)):blank();}catch(e){state=blank();storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}$('#storage-warning').classList.toggle('hidden',storageOK);}
function ms(m){return state.modules[m.id];}
function best(m){return ms(m).attempts.reduce((b,a)=>Math.max(b,a.score/a.total*100),0);}
function pass(m){return best(m)>=80;}
function practiceDone(m){return m.activities.every((a,i)=>ms(m).activities[i]?.done)&&ms(m).lab;}
function complete(m){return ms(m).read.length===m.lessons.length&&practiceDone(m)&&pass(m);}
function completionCount(){return COURSE.filter(complete).length;}
function percent(m){return Math.round((ms(m).read.length+m.activities.filter((a,i)=>ms(m).activities[i]?.done).length+(ms(m).lab?1:0)+(pass(m)?1:0))/(m.lessons.length+m.activities.length+2)*100);}
function globalPercent(){return Math.round(COURSE.reduce((s,m)=>s+percent(m),0)/COURSE.length);}
function clockText(){let n=Math.floor(state.seconds);return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.remove('hidden');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.add('hidden'),4000);}
function setCompleteDate(){if(completionCount()===COURSE.length&&!state.completedAt)state.completedAt=new Date().toISOString();}

function profileComplete(){return !!(state.name.trim()&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(state.email)&&state.storeName.trim()&&state.storeNumber.trim());}
function storeLabel(){return `${state.storeName} (Store #${state.storeNumber})`;}
function personalNote(text){return `<p class="personal-note">${esc(state.name)}, ${esc(text)}</p>`;}
function welcome(){let returning=profileComplete();return `<div class="welcome-layout"><section class="welcome-intro"><div class="eyebrow">INS Market · Operations Manual Training</div><h1>${returning?'Your franchisee profile':'Welcome to your Operations Manual Training.'}</h1><p class="muted">${returning?'Update the details used throughout your training and on your completion record.':'Before you begin, enter your details so we can make this training yours.'}</p><div class="welcome-facts"><span>9 modules</span><span>${TOTAL_QUESTIONS} questions</span><span>${esc(DURATION_LABEL)}</span></div><p class="small muted">Your details and progress are saved in this browser. Your name and store will appear throughout the course and on your completion page. ${certificateEmailConfigured()?'When you begin, your name, email and store details are sent to Terry at terry@thedavisgroup.ca. When you finish, your PDF certificate is submitted by email to you and Terry.':'Your email is included on your PDF certificate and progress export. A PDF download is available when you finish.'}</p></section><section class="panel welcome-form-panel"><div class="eyebrow">Your details</div><h2>${returning?'Edit your profile':'Let’s get started'}</h2><form id="profile-form"><label class="field">Franchisee’s full name<input id="profile-name" name="name" required maxlength="120" autocomplete="name" value="${esc(state.name)}" placeholder="Enter your full name"></label><label class="field">Email address<input id="profile-email" name="email" type="email" required maxlength="254" autocomplete="email" value="${esc(state.email)}" placeholder="name@example.com"></label><div class="form-grid two"><label class="field">Store name<input id="profile-store-name" name="storeName" required maxlength="120" autocomplete="organization" value="${esc(state.storeName)}" placeholder="Enter your store name"></label><label class="field">Store number<input id="profile-store-number" name="storeNumber" type="text" required maxlength="40" value="${esc(state.storeNumber)}" placeholder="e.g. 0042"></label></div><p id="profile-error" class="error" role="alert"></p><button class="button" type="submit">${returning?'Save details & continue':'Save details & begin training'} →</button></form></section></div>${footer()}`;}
function congratulations(){if(completionCount()!==COURSE.length)return `<div class="eyebrow">Your course finish line</div><h1>Keep going, ${esc(state.name)}.</h1><section class="panel"><h2>Your congratulations page will unlock when you pass.</h2><p>You have completed <strong>${completionCount()} of 9 modules</strong>. Finish every reading and practice activity and pass each module’s knowledge check with at least 80%.</p><a class="button" href="#/home">Continue your training →</a></section>${footer()}`;
 const date=state.completedAt?new Date(state.completedAt).toLocaleDateString('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'long',day:'numeric'}):'';
 return `<section class="congratulations"><div class="completion-seal" aria-hidden="true">✓</div><div class="eyebrow">INS Market · Course completed</div><h1>Congratulations, ${esc(state.name)}!</h1><p class="congratulations-message"><strong>${esc(state.name)}</strong> from <strong>${esc(storeLabel())}</strong>, you have passed the INS Market Operations Manual Training course.</p><p class="muted">You completed all nine modules and their reading and practice activities, and passed every knowledge check. Well done on reaching this milestone.</p><div class="completion-details"><div><span>Franchisee</span><strong>${esc(state.name)}</strong></div><div><span>Store</span><strong>${esc(storeLabel())}</strong></div><div><span>Email</span><strong>${esc(state.email)}</strong></div><div><span>Completion date</span><strong>${esc(date)}</strong></div></div><div class="completion-metrics"><span><strong>9/9</strong> modules completed</span><span><strong>${TOTAL_QUESTIONS}</strong> knowledge-check questions</span><span><strong>Passed</strong> every module</span></div><div class="actions"><a class="button" href="#/record">View / print your completion record →</a><a class="secondary" href="#/home">Review your training</a><a class="ghost" href="#/quiz/9">Review the final knowledge check</a></div>${certificateDeliveryPanel()}<p class="small muted completion-footnote">This confirms completion of this course. Your INS practical training and any required external certifications remain separate.</p></section>${footer()}`;
}

function footer(){return `<footer class="footer"><span>INS Market · Operations Manual Training · Learning edition 14 November 2026</span></footer>`;}
function badge(m){return complete(m)?'<span class="pill green">✓ Complete</span>':percent(m)?'<span class="pill gold">In progress</span>':'<span class="pill">Not started</span>';}
function routeLabel(){let a=location.hash.split('/');return a[1]||'home';}
function sidebar(){let a=location.hash.split('/'),current=Number(a[2]),page=a[1]||'home';$('#sidebar').innerHTML=`${profileComplete()?`<a class="learner-profile" href="#/welcome" aria-label="Edit your franchisee profile"><span>Training for</span><strong>${esc(state.name)}</strong><small>${esc(storeLabel())}</small></a>`:''}<a href="#/home" class="nav-link ${page==='home'?'active':''}"><span class="nav-num">⌂</span><span class="nav-title">Your learning path</span></a><div class="side-progress"><div class="label"><span>Course progress</span><strong>${globalPercent()}%</strong></div><div class="track"><span style="width:${globalPercent()}%"></span></div><div class="small" style="font-size:10px;margin-top:8px;color:#aab7c0">${completionCount()} of 9 modules complete</div></div><div class="nav-label">The modules</div>${COURSE.map(m=>`<a href="#/module/${m.id}" class="nav-link ${current===m.id&&['module','read','practice','quiz'].includes(page)?'active':''} ${complete(m)?'done':''}" ${current===m.id&&['module','read','practice','quiz'].includes(page)?'aria-current="page"':''}><span class="nav-num">${complete(m)?'✓':String(m.id).padStart(2,'0')}</span><span><span class="nav-title">${esc(m.short)}</span><span class="nav-sub">${m.minutes} min · ${m.questions.length} questions</span></span></a>`).join('')}<a href="#/congratulations" class="nav-link ${page==='congratulations'?'active':''}"><span class="nav-num">${completionCount()===9?'✓':'☆'}</span><span class="nav-title">Your congratulations page</span></a><div class="nav-label">Your resources</div><a href="#/library" class="nav-link ${page==='library'?'active':''}"><span class="nav-num">▤</span><span class="nav-title">Reference library & forms</span></a><a href="#/record" class="nav-link ${page==='record'?'active':''}"><span class="nav-num">✓</span><span class="nav-title">Progress & completion record</span></a><div class="side-note">Read. Practise. Check your understanding.<br><br>Progress stays in this browser. Export a backup to move between computers.</div>`;}
function imgButton(key,alt,cl=''){if(!ASSETS[key])return '';return `<button class="image-button ${cl}" data-image="${esc(key)}" data-caption="${esc(alt)}" aria-label="Enlarge image: ${esc(alt)}"><img src="${ASSETS[key]}" alt="${esc(alt)}" loading="lazy"></button>`;}
function visual(l){if(!l.visual)return '';let v=l.visual,c=l.caption||'',html='',photo=false;
 if(['store','storewide','marketing','freezer','form','lottery','alcoholplan','deposit','responsible','pos','chase','prepay','fraud','cooler'].includes(v)){html=imgButton(v,c);photo=['store','storewide'].includes(v);}
 if(v==='flow')html='<div class="graphic process" role="img" aria-label="Identify the issue, contact Help Desk, keep the ticket, Field Manager escalation if unresolved"><div><b>01</b><span>Identify the issue</span></div><div><b>02</b><span>Email Help Desk</span></div><div><b>03</b><span>Keep the ticket</span></div><div><b>04</b><span>Resolve or escalate</span></div></div>';
 if(v==='audit')html='<div class="graphic process" role="img" aria-label="Identify the audit program, confirm the report, correct deficiencies, record evidence"><div><b>01</b><span>Name the program</span></div><div><b>02</b><span>Read the report</span></div><div><b>03</b><span>Correct on time</span></div><div><b>04</b><span>Document the result</span></div></div>';
 if(v==='margin')html='<div class="graphic mini-bars" role="img" aria-label="One hundred dollars of sales consists of eighty dollars of product cost and twenty dollars of gross profit"><div class="bar"><span>Sales</span><i style="width:65%"></i><strong>$100</strong></div><div class="bar"><span>Product cost</span><i style="width:52%"></i><strong>$80</strong></div><div class="bar"><span>Gross profit</span><i style="width:13%"></i><strong>$20</strong></div></div>';
 if(v==='service')html='<div class="graphic service-graphic" role="img" aria-label="Five sales standards: greet, understand needs, recommend, register, thank"><div><b>1</b><span>Greet</span></div><div><b>2</b><span>Understand</span></div><div><b>3</b><span>Recommend</span></div><div><b>4</b><span>Register</span></div><div><b>5</b><span>Thank</span></div></div>';
 if(v==='temperature')html='<div class="graphic temp-graphic" role="img" aria-label="Potentially hazardous food: cold holding at 4 degrees Celsius or below, out of holding range between 4 and 60, hot holding at 60 or above"><div><b>≤ 4°C</b><span>Cold holding</span></div><div><b>4–60°C</b><span>Outside safe holding limits</span></div><div><b>≥ 60°C</b><span>Hot holding</span></div></div>';
 if(v==='promo')html='<div class="graphic mini-bars" role="img" aria-label="Illustrative gross profit rises from three thousand four hundred thirty-two dollars to three thousand nine hundred seventy-two dollars at the stated fifty-percent multi-buy uptake"><div class="bar"><span>Single only</span><i style="width:52%"></i><strong>$3,432</strong></div><div class="bar"><span>50% uptake</span><i style="width:60%"></i><strong>$3,972</strong></div></div>';
 if(!html&&ASSETS[v])html=imgButton(v,c);
 return html?`<figure class="visual ${photo?'photo':''}">${html}<figcaption>${esc(c)} ${ASSETS[v]?'Select the image to enlarge.':''}</figcaption></figure>`:'';
}
function moduleTabs(m,page){return `<nav class="tabs" aria-label="Module sections"><a class="tab ${page==='module'?'active':''}" href="#/module/${m.id}">Overview</a><a class="tab ${page==='read'?'active':''}" href="#/read/${m.id}/0">Reading ${ms(m).read.length}/${m.lessons.length}</a><a class="tab ${page==='practice'?'active':''}" href="#/practice/${m.id}">Practice ${practiceDone(m)?'✓':''}</a><a class="tab ${page==='quiz'?'active':''}" href="#/quiz/${m.id}">Knowledge check ${pass(m)?'✓':''}</a></nav>`;}
function editionNotice(){return state.earlierEdition?`<section class="notice neutral no-print"><strong>Your earlier training record is saved.</strong><p>The expanded Operations Manual Training adds readings and at least 30 questions in every module, with extra questions on alcohol, workplace safety and payment security. Your earlier record and any certificate details remain available in a separate backup. Completed readings, practical activities and notes have been carried forward.</p><button class="secondary" id="export-earlier">Download earlier training backup</button></section>`:'';}
function home(){let next=COURSE.find(m=>!complete(m))||COURSE[0],target=completionCount()===9?'#/congratulations':state.last||`#/module/${next.id}`;return `${editionNotice()}<div class="eyebrow">Franchise owner & store manager development</div><section class="hero"><div class="hero-copy"><h1>Welcome${globalPercent()?' back':''}, ${esc(state.name)}.</h1><p>Build the knowledge to lead <strong>${esc(storeLabel())}</strong>, support your team and deliver INS standards every day.</p><div class="actions"><a class="button" href="${target}">${completionCount()===9?'View your congratulations':globalPercent()?'Continue training':'Start your training'} <span aria-hidden="true">→</span></a><a class="ghost" href="#course-path">Explore the modules ↓</a></div></div><div class="hero-picture"><img src="${ASSETS.store}" alt="An INS Market store with branded beverage coolers and stocked snack shelves"><span class="photo-tag">INS MARKET · OPERATIONS TRAINING</span></div></section><div class="metrics"><div class="metric"><strong>${PLANNED_MINUTES}</strong><span>minutes of self-paced learning</span></div><div class="metric"><strong>9</strong><span>modules, with reading & practice</span></div><div class="metric"><strong>${TOTAL_QUESTIONS}</strong><span>questions with explanations</span></div><div class="metric"><strong>${globalPercent()}%</strong><span>your course progress</span></div></div><div class="two-col"><section class="panel"><div class="eyebrow">Your route through the course</div><h2>Read it. Try it. Apply it.</h2><p class="small muted">Review each reading, complete two workplace scenarios and a practical lab, then take the module’s knowledge check.</p><div class="planner"><span>18 scenarios</span><span>9 practical labs</span><span>30–40 questions per module</span></div></section><section class="panel"><div class="eyebrow">Completion and pacing</div><h2>Learn at your own pace</h2><p class="small muted">Plan for about six hours of readings, practical activities and 290 questions. Follow the module time guides, pause to work through each decision exercise and take breaks when needed. Take breaks and return when you need to. Actual pace varies. Finish all readings and activities and score at least 80% in each module to unlock the course completion record.</p><p class="small muted">80% is this course’s learning threshold. INS practical certification and approved alcohol training remain separate.</p></section></div><div id="course-path" class="section-title"><h2>Your learning path</h2><span class="small muted">${completionCount()} of 9 complete</span></div><section class="module-grid">${COURSE.map(m=>`<article class="module-card"><div class="card-top"><span class="number">${String(m.id).padStart(2,'0')}</span>${badge(m)}</div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="card-bottom"><div class="small muted" style="margin-bottom:10px">${m.minutes} min · ${m.lessons.length} readings · ${m.questions.length} questions</div><div class="track"><span style="width:${percent(m)}%"></span></div><a class="link" href="#/module/${m.id}">${complete(m)?'Review module':percent(m)?'Continue module':'Open module'} <span aria-hidden="true">→</span></a></div></article>`).join('')}</section><div class="notice neutral">Ontario lottery, alcohol and employment examples are labelled in the relevant modules. Apply the requirements for your store’s jurisdiction.</div>${footer()}`;}
function plan(m){return {read:m.readMinutes,practice:m.practiceMinutes,quiz:m.quizMinutes};}
function overview(m){let t=plan(m),first=m.lessons.findIndex((l,i)=>!ms(m).read.includes(i));return `<div class="breadcrumb"><a href="#/home">Learning path</a> / Module ${m.id}</div><div class="eyebrow">Module ${String(m.id).padStart(2,'0')}</div><h1>${esc(m.title)}</h1>${personalNote('here is what you will learn in this module.')}<p class="muted">${esc(m.description)}</p><div class="module-meta">${badge(m)}<span>${m.minutes} minutes</span><span>${m.questions.length} questions</span><span>${percent(m)}% complete</span></div>${moduleTabs(m,'module')}<div class="journey"><div class="panel"><div><strong>${t.read} min</strong><span>Read & review</span></div><span>${m.lessons.length} short readings</span></div><div class="panel"><div><strong>${t.practice} min</strong><span>Practise decisions</span></div><span>2 scenarios + a lab</span></div><div class="panel"><div><strong>${t.quiz} min</strong><span>Check understanding</span></div><span>${m.questions.length} questions</span></div></div><section class="panel"><h2>By the end, you can…</h2><ul class="goals">${m.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><div class="actions"><a class="button" href="#/read/${m.id}/${first<0?0:first}">${ms(m).read.length?'Continue reading':'Begin reading'} →</a><a class="secondary" href="#/practice/${m.id}">Open practice</a></div></section><section class="panel"><h2>Reading in this module</h2><ol class="lesson-list">${m.lessons.map((l,i)=>`<li><a href="#/read/${m.id}/${i}"><span class="tick">${ms(m).read.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${esc(l.title)}</span>${ms(m).read.includes(i)?'<span class="review-badge" style="margin-left:auto">Reviewed</span>':''}</a></li>`).join('')}</ol></section>${footer()}`;}
function read(m,index){index=Math.min(Math.max(Number(index)||0,0),m.lessons.length-1);let l=m.lessons[index],done=ms(m).read.includes(index),next=index+1<m.lessons.length?`#/read/${m.id}/${index+1}`:`#/practice/${m.id}`;return `<div class="breadcrumb"><a href="#/home">Learning path</a> / <a href="#/module/${m.id}">Module ${m.id}</a> / Reading ${index+1}</div>${moduleTabs(m,'read')}<div class="lesson-layout"><article class="reading"><div class="eyebrow">Reading ${index+1} of ${m.lessons.length} · ${esc(m.short)}</div><h2>${esc(l.title)}</h2>${personalNote('read through this lesson and consider how it applies at your store.')}${visual(l)}${l.body}<div class="reading-footer"><div class="actions"><button class="button" data-read="${index}" data-module="${m.id}" data-next="${next}">${done?'Reviewed · Continue':'Mark reviewed & continue'} →</button>${index>0?`<a class="ghost" href="#/read/${m.id}/${index-1}">Previous reading</a>`:''}</div><p class="source-line">Mark reviewed after reading and considering how this applies at your store.</p></div></article><nav class="lesson-aside" aria-label="Readings in module"><h3>In this module</h3>${m.lessons.map((s,i)=>`<a href="#/read/${m.id}/${i}" class="${i===index?'active':''} ${ms(m).read.includes(i)?'reviewed':''}" ${i===index?'aria-current="step"':''}><span class="step-icon">${ms(m).read.includes(i)?'✓':i+1}</span><span>${esc(s.title)}</span></a>`).join('')}<a href="#/practice/${m.id}"><span class="step-icon">↗</span><span>Practice lab</span></a></nav></div>${footer()}`;}
function labFields(m){let v=ms(m).labValues;
 const num=(name,label,placeholder='')=>`<label class="field">${label}<input type="number" step="any" name="${name}" value="${esc(v[name]??'')}" placeholder="${esc(placeholder)}" inputmode="decimal" autocomplete="off"></label>`;
 const sel=(name,label,options)=>`<div class="form-row"><span>${label}</span><label class="field"><span class="hidden">Choose for ${esc(label)}</span><select name="${name}" aria-label="${esc(label)}"><option value="">Choose…</option>${optionIndexes(options,`lab-${m.id}-${name}`).map(i=>`<option value="${i}" ${String(v[name])===String(i)?'selected':''}>${esc(options[i])}</option>`).join('')}</select></label></div>`;
 const check=(name,label)=>`<label class="lab-check"><input type="checkbox" name="${name}" ${v[name]===true?'checked':''}>${esc(label)}</label>`;
 let body='',title='',intro='';
 if(m.id===1){title='Numbers you can explain';intro='An item costs $80 and sells for $100. Separately, starting cash is $2,000, cash in is $8,000 and cash out is $7,500. Calculate all three answers.';body=`<div class="form-grid">${num('margin','Gross margin (%)','e.g. 20')}${num('markup','Markup (%)')}${num('cash','Ending cash ($)')}</div><p class="quiz-hint">Margin uses selling price. Markup uses cost. Ending cash uses cash movements.</p>`;}
 if(m.id===2){title='Match the compliance program';intro='Match each operating requirement to the program that describes it. Do not combine charges automatically.';let o=['Levels to Excellence','Planogram compliance audit','Mystery Shop sales registration'];body=sel('audit0','$250 + HST failed-audit charge',o)+sel('audit1','First correction within seven business days',o)+sel('audit2','First failure: $150 + written warning',o);}
 if(m.id===3){title='Build the five-step interaction';intro='Put the INS sales standards in their correct order.';let o=['Greet or acknowledge','Understand the need','Offer a relevant promotion/add-on','Register correctly and offer a receipt','Thank and invite back'];body=[1,2,3,4,5].map((n,i)=>sel('step'+i,'Step '+n,o)).join('');}
 if(m.id===4){title='Check the temperature log';intro='Classify these internal food readings for potentially hazardous food. Assume it is being held for sale, rather than actively cooked.';let o=['Within cold-holding limit','Within hot-holding limit','Outside the holding limit: stop sale and follow corrective procedure'];body=sel('temp0','Chilled sandwich: 2°C',o)+sel('temp1','Hot-held food: 58°C',o)+sel('temp2','Hot-held food: 64°C',o);}
 if(m.id===5){title='Calculate an offer’s return';intro='A two-unit promotion sells for $6.00 and costs $4.12 for the pair. Calculate gross profit per pair and gross margin. Round margin to one decimal place.';body=`<div class="form-grid two">${num('profit','Gross profit per pair ($)')}${num('margin','Gross margin (%)')}</div>`;}
 if(m.id===6){title='Put the incident response in order';intro='A worker is injured and needs medical help. Put these response stages in their correct order.';let o=['Arrange first aid/emergency care','Record facts and meet separate reporting duties','Review hazards and safe suitable work/follow-up'];body=[1,2,3].map((n,i)=>sel('incident'+i,'Stage '+n,o)).join('');}
 if(m.id===7){title='Three lottery decisions';intro='Choose the correct response for each situation.';let o=['Check acceptable ID under ID25 before processing','Do not print: customer must be present','Call OLG immediately; do not check/validate/cancel'];body=sel('lottery0','A customer who appears 22 asks to validate a ticket',o)+sel('lottery1','A customer phones from home to request a ticket',o)+sel('lottery2','A customer’s ticket is found on the floor',o);}
 if(m.id===8){title='Calculate the deposits';intro='Use container size and type. Enter the total deposit in dollars for each purchase.';body=`<div class="form-grid">${num('can6','Six 355 mL metal cans ($)')}${num('wine2','Two 750 mL glass bottles ($)')}${num('largecan','One 1.5 L metal can ($)')}</div>`;}
 if(m.id===9){title='Stop a phone activation scam';intro='Select every appropriate action when a caller claims to be support and asks for a prepaid test activation.';const choices=[check('stop','Stop the activation and disclose no PIN.'),check('verify','Verify using a known supplier contact, not a number supplied by the caller.'),check('report','Notify the manager through the approved process.'),check('small','Activate a small amount first to see whether the caller is legitimate.'),check('bypass','Answer the security prompt inaccurately to continue.')];body=optionIndexes(choices,'lab-9-checks').map(i=>choices[i]).join('');}
 return `<section class="scenario"><span class="eyebrow">Practical lab ${ms(m).lab?'· ✓ Completed':''}</span><h3>${title}</h3><p class="prompt">${intro}</p><form id="lab-form" data-module="${m.id}">${body}<button class="secondary" type="submit">Check my work</button><div id="lab-feedback" aria-live="polite">${ms(m).lab?'<div class="feedback good"><strong>Lab completed</strong>You can change the entries and check your work again.</div>':''}</div></form></section>`;
}
function practice(m){return `<div class="breadcrumb"><a href="#/module/${m.id}">Module ${m.id}</a> / Practice</div><div class="eyebrow">Apply what you read</div><h1>Put it into practice, ${esc(state.name)}.</h1><p class="muted">Try each decision, read the feedback and complete the lab. These activities prepare you for the ${m.questions.length}-question knowledge check.</p>${moduleTabs(m,'practice')}${m.activities.map((a,i)=>{let r=ms(m).activities[i];return `<section class="scenario"><span class="eyebrow">Scenario ${i+1} ${r?.done?'· ✓ Completed':''}</span><h3>${esc(a.title)}</h3><p class="prompt">${esc(a.prompt)}</p><div>${optionIndexes(a.options,`scenario-${m.id}-${i}`).map(j=>{const o=a.options[j];return `<button class="choice-btn ${r?.choice===j?(j===a.answer?'correct':'selected'):''}" data-scenario="${i}" data-choice="${j}" data-module="${m.id}" aria-pressed="${r?.choice===j}">${esc(o)}</button>`;}).join('')}</div>${r?`<div class="feedback ${r.choice===a.answer?'good':''}" role="status"><strong>${r.choice===a.answer?'That is the right action.':'Consider the consequence, then try again.'}</strong>${esc(a.why)}</div>`:''}</section>`;}).join('')}${labFields(m)}<section class="panel"><h2>One action for your store</h2><p class="small muted">Write one thing you will check or improve on your next shift. Keep this note free of passwords, payment details and private employee/customer information.</p><label class="field">Your action note (optional)<textarea id="reflection" maxlength="3000" data-module="${m.id}" placeholder="On my next shift, I will…">${esc(ms(m).reflection)}</textarea></label><span class="save-label" id="note-status">Saved in this browser as you type.</span></section><div class="notice ${practiceDone(m)?'green':'neutral'}">${practiceDone(m)?'✓ Practice complete. Continue to the knowledge check.':'Complete both scenarios correctly and check the lab answers to finish the practice section.'}</div><div class="actions"><a class="button" href="#/quiz/${m.id}">Open knowledge check →</a><a class="secondary" href="#/module/${m.id}">Back to overview</a></div>${footer()}`;}
function checkLab(m,values){let v=Object.fromEntries(values),ok=false,why='';
const close=(key,n,tol=.011)=>v[key]!==''&&Number.isFinite(Number(v[key]))&&Math.abs(Number(v[key])-n)<=tol;
const list=(names,answers)=>names.every((name,i)=>v[name]===String(answers[i]));
if(m.id===1){ok=close('margin',20)&&close('markup',25)&&close('cash',2500);why='Margin = 20 ÷ 100 = 20%. Markup = 20 ÷ 80 = 25%. Cash = 2,000 + 8,000 − 7,500 = $2,500.';}
if(m.id===2){ok=list(['audit0','audit1','audit2'],[0,1,2]);why='Levels to Excellence lists $250 + HST. The planogram program gives seven business days. Mystery Shop sales-registration failure starts at $150 plus a warning.';}
if(m.id===3){ok=list(['step0','step1','step2','step3','step4'],[0,1,2,3,4]);why='Greet, understand, recommend, register correctly with a receipt, then thank and invite back.';}
if(m.id===4){ok=list(['temp0','temp1','temp2'],[0,2,1]);why='2°C meets cold holding at 4°C or below. 58°C is below 60°C hot holding and needs the approved corrective procedure. 64°C meets the hot-holding limit.';}
if(m.id===5){ok=close('profit',1.88)&&close('margin',31.3,.06);why='Gross profit per pair = $6 − $4.12 = $1.88. Gross margin = 1.88 ÷ 6 × 100 = 31.3%.';}
if(m.id===6){ok=list(['incident0','incident1','incident2'],[0,1,2]);why='Care comes first, followed by accurate reporting on each applicable deadline and then hazard correction and safe-work follow-up.';}
if(m.id===7){ok=list(['lottery0','lottery1','lottery2'],[0,1,2]);why='Use ID25 for the young-looking customer, require presence for purchase and report a found ticket to OLG without checking it.';}
if(m.id===8){ok=close('can6',.6)&&close('wine2',.4)&&close('largecan',.2);why='Six 10-cent can deposits = $0.60. Two 20-cent bottle deposits = $0.40. A metal can over 1 L has a $0.20 deposit.';}
if(m.id===9){ok=['stop','verify','report'].every(k=>v[k]==='on')&&!v.small&&!v.bypass;why='Stop, disclose no PIN, verify through a known contact and report. Do not test an activation or bypass the security questions.';}
return {ok,why};}
function quiz(m){let s=ms(m),latest=!s.retake?s.attempts.at(-1):null,needed=Math.ceil(.8*m.questions.length);let readiness=s.read.length===m.lessons.length&&practiceDone(m);return `<div class="breadcrumb"><a href="#/module/${m.id}">Module ${m.id}</a> / Knowledge check</div><div class="eyebrow">Show what you know</div><h1>${esc(m.short)}: knowledge check</h1>${personalNote('take your time and choose the best answer for each question.')}<p class="muted">${m.questions.length} questions. One best answer each. Answer all questions, then submit to see your score and explanations.</p>${moduleTabs(m,'quiz')}${latest?`<div class="score-card ${latest.score/latest.total<.8?'fail':''}"><div class="score">${latest.score}/${latest.total}</div><div><h2>${latest.score/latest.total>=.8?`Well done, ${esc(state.name)} — you passed`:`${esc(state.name)}, review and try again`}</h2><p>${Math.round(latest.score/latest.total*100)}% on this attempt. Pass mark: ${needed}/${m.questions.length}. Best score: ${Math.round(best(m))}%.<br>${complete(m)?'✓ This module is complete.':pass(m)?'Your quiz pass is saved. Finish any remaining readings or practice to complete the module.':'Review the explanations below and revisit the readings before retrying.'}</p></div></div><div class="actions score-actions"><button class="secondary" id="retake" data-module="${m.id}">Retake knowledge check</button><a class="button" href="${complete(m)&&m.id<9?'#/module/'+(m.id+1):complete(m)?'#/congratulations':'#/module/'+m.id}">${complete(m)&&m.id<9?'Next module →':complete(m)?'See your congratulations →':'Finish module activities →'}</a></div>`:`<div class="notice neutral">Pass this check with at least 80% (${needed}/${m.questions.length} correct). ${!readiness?'You can try the check now. Complete all readings and practice as well to finish the module.':'Your reading and practice are complete.'} Your answers save as you choose them.</div>`}<form id="quiz-form" data-module="${m.id}" novalidate>${m.questions.map((q,i)=>{let chosen=latest?latest.answers[i]:s.draft[i],right=chosen===q.answer;return `<div class="quiz-question" id="question-${i}"><span class="question-number">Question ${i+1} of ${m.questions.length}</span><fieldset><legend>${esc(q.prompt)}</legend>${optionIndexes(q.options,`quiz-${m.id}-${i}-${latest?s.attempts.length-1:s.attempts.length}`).map(j=>{const o=q.options[j];return `<label class="radio ${latest&&j===q.answer?'correct-answer':''} ${latest&&chosen===j&&!right?'wrong-answer':''}"><input type="radio" name="q${i}" value="${j}" ${chosen===j?'checked':''} ${latest?'disabled':''} aria-label="${esc(o)}"><span>${esc(o)}${latest&&j===q.answer?' <strong>✓ Correct answer</strong>':''}${latest&&chosen===j?' <em>— Your answer</em>':''}</span></label>`;}).join('')}</fieldset>${latest?`<div class="feedback ${right?'good':''}"><strong>${right?'Correct.':'Review this point.'}</strong>${esc(q.why)}</div>`:''}</div>`;}).join('')}${!latest?`<div id="quiz-error" class="error" role="alert"></div><div class="quiz-submit"><span id="answer-count">${Object.keys(s.draft).length} of ${m.questions.length} answered</span><button class="button" type="submit">Submit knowledge check</button></div>`:''}</form>${latest?`<div class="actions"><a class="secondary" href="#/module/${m.id}">Module overview</a><a class="button" href="${complete(m)&&m.id<9?'#/module/'+(m.id+1):complete(m)?'#/congratulations':'#/read/'+m.id+'/0'}">${complete(m)&&m.id<9?'Next module →':complete(m)?'See your congratulations →':'Review reading →'}</a></div>`:''}${footer()}`;}
function library(){let sp=new URLSearchParams(location.hash.split('?')[1]||''),filter=sp.get('module')||'all';return `<div class="eyebrow">Keep the details close</div><h1>Reference library & forms</h1><p class="muted">Search operating procedures, equipment guides and appendix forms. Select a reference to read the details and enlarge available visuals.</p><div class="notice neutral">Use the current approved procedures for your location. Historical forms and reference examples may require updates; follow the operational instructions in the lessons and the guidance shown with the relevant reference.</div><div class="search-bar"><label class="field">Search references<input id="library-search" type="search" placeholder="Try: freezer, audit, deposit, temperature…" autocomplete="off"></label><label class="field">Filter by course module<select id="library-filter"><option value="all">All modules</option>${COURSE.map(m=>`<option value="${m.id}" ${filter===String(m.id)?'selected':''}>${m.id}. ${esc(m.short)}</option>`).join('')}<option value="attached">Operating procedures</option><option value="forms">Appendix forms</option></select></label></div><p class="small muted" id="library-count" role="status"></p><div id="library-results"></div>${footer()}`;}
function referenceCards(){let q=($('#library-search').value||'').trim().toLowerCase(),filter=$('#library-filter').value;let found=REFERENCES.filter(r=>(filter==='all'||filter==='attached'&&r.attached||filter==='forms'&&r.attached&&r.slide>=86||r.modules.includes(Number(filter)))&&(!q||(r.title+' '+r.text+' '+(r.extra||'')+' '+r.source).toLowerCase().includes(q)));$('#library-count').textContent=`${found.length} references found · ${REFERENCES.filter(r=>r.attached).length} operating-procedure entries`;$('#library-results').innerHTML=found.map(r=>`<details class="reference-entry"><summary><small>${esc(r.manualLabel||r.source)} · Reference ${r.slide} · Course ${r.modules.map(n=>'M'+n).join(', ')}</small>${esc(r.title)}</summary><div class="reference-content">${r.flag?`<div class="notice">${esc(r.flag)}</div>`:''}${r.extra?`<p class="small">${esc(r.extra)}</p>`:''}<pre>${esc(r.text||'See the illustration or description below.')}</pre>${r.images?.length?`<div class="reference-gallery">${r.images.map(im=>`<figure>${imgButton(im.key,im.caption)}<figcaption>${esc(im.caption)}</figcaption></figure>`).join('')}</div>`:''}</div></details>`).join('')||'<div class="empty">No matching references. Try a shorter phrase or a different filter.</div>';}
function record(){let done=completionCount()===9,completed=state.completedAt?new Date(state.completedAt).toLocaleDateString('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'long',day:'numeric'}):'Not yet complete';return `${editionNotice()}<div class="eyebrow no-print">Your learning record</div><h1 class="no-print">${esc(state.name)}, here is your progress.</h1><section class="panel record-inputs"><h2>${esc(state.name)}, your franchisee details</h2><div class="completion-details"><div><span>Franchisee name</span><strong>${esc(state.name)}</strong></div><div><span>Email address</span><strong>${esc(state.email)}</strong></div><div><span>Store name</span><strong>${esc(state.storeName)}</strong></div><div><span>Store number</span><strong>${esc(state.storeNumber)}</strong></div></div><p class="small muted">Your progress stays in this browser. ${certificateEmailConfigured()?'After completion, your PDF certificate and franchisee/store details are submitted by email to you and terry@thedavisgroup.ca.':'Your PDF certificate is available to download after completion.'}</p><div class="actions"><a class="secondary" href="#/welcome">Edit your details</a><button class="secondary" id="export">Export progress backup</button><button class="secondary" id="import">Import progress backup</button><input id="import-file" type="file" accept=".json,application/json" class="hidden"><button class="ghost" id="reset">Reset this course</button></div></section><section class="panel certificate" id="completion-record"><div class="record-header"><img src="${ASSETS.logo}" alt="INS Market logo"><div><h2>Operations Manual Training</h2><p>${done?'Course completion record':'Course progress record'} · Learning edition 14 November 2026</p></div></div><p><strong id="record-name">${esc(state.name||'Learner name not entered')}</strong><br><span class="muted" id="record-store">${esc(storeLabel())}</span><br><span class="small muted">${esc(state.email)}</span></p><div class="record-summary"><div><strong>${completionCount()}/9</strong><span>modules complete</span></div><div><strong>${PLANNED_MINUTES} min</strong><span>planned course duration</span></div><div><strong id="record-time">${clockText()}</strong><span>recorded active study time</span></div></div><p class="small"><strong>Completion date:</strong> ${esc(completed)}</p><div class="table-wrap"><table class="record-table"><thead><tr><th>Module</th><th>Reading</th><th>Practice</th><th>Best quiz</th><th>Status</th></tr></thead><tbody>${COURSE.map(m=>`<tr><td>${m.id}. ${esc(m.title)}</td><td>${ms(m).read.length}/${m.lessons.length}</td><td>${practiceDone(m)?'Complete':'Pending'}</td><td>${ms(m).attempts.length?Math.round(best(m))+'%':'Not taken'}</td><td>${complete(m)?'Complete':'In progress'}</td></tr>`).join('')}</tbody></table></div><div class="notice ${done?'green':'neutral'}">${done?'The learner completed all course readings and practice activities and achieved at least 80% on every module knowledge check.':'Complete every reading and practice activity and achieve at least 80% on each module check to unlock the course completion record.'}</div><p class="small muted">This record documents completion of the INS Market Operations Manual Training. It does not replace INS franchisee/staff certification, observed practical sign-off or required AGCO-approved alcohol training. Results are browser-local and are not independently proctored.</p><div class="signature"><span>Learner acknowledgement / date</span></div><p class="source-line">Course plan: 9 modules / ${TOTAL_QUESTIONS} questions / ${PLANNED_MINUTES} planned minutes.</p></section><div class="actions no-print" style="margin-top:22px">${done?'<a class="secondary" href="#/congratulations">View your congratulations page</a>':''}<button class="button" id="print" ${done?'':'disabled'}>Print / save completion record</button><button class="secondary" id="results">Download results summary</button></div>${!done?'<p class="small muted no-print">Printing unlocks after all nine modules are complete. Your progress backup is available at any time.</p>':''}<section class="panel no-print"><h2>Your action notes</h2>${COURSE.map(m=>`<details class="policy-item"><summary>${m.id}. ${esc(m.short)}</summary><p style="white-space:pre-wrap">${esc(ms(m).reflection||'No action note saved yet.')}</p><a class="small" href="#/practice/${m.id}">Edit note</a></details>`).join('')}</section>${footer()}`;}
let lastRoute='',lastActivity=Date.now(),lastTick=Date.now();
function render(){let scroll=lastRoute!==location.hash;lastRoute=location.hash;let hash=location.hash||'#/home',a=hash.split('?')[0].split('/'),page=a[1]||'home',m=mod(a[2]),content='';
 if(!profileComplete()&&page!=='welcome'){location.hash='#/welcome';return;}
 if(['module','read','practice','quiz'].includes(page)&&!m){location.hash='#/home';return;}
 if(m&&['module','read','practice','quiz'].includes(page)){state.last=hash;save();}
 if(page==='welcome')content=welcome();else if(page==='congratulations')content=congratulations();else if(page==='home')content=home();else if(page==='module')content=overview(m);else if(page==='read')content=read(m,a[3]);else if(page==='practice')content=practice(m);else if(page==='quiz')content=quiz(m);else if(page==='library')content=library();else if(page==='record')content=record();else if(page==='sources'){location.hash='#/home';return;}else{location.hash='#/home';return;}
 $('#main').innerHTML=`<div class="container">${page!=='welcome'?signOnNotificationPanel():''}${content}</div>`;sidebar();$('#sidebar').classList.remove('open');$('#backdrop').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');
 document.title=`${page==='welcome'?'Your franchisee profile':page==='congratulations'?'Congratulations':m?m.title:page==='home'?'Operations Manual Training':page==='library'?'Reference library':page==='record'?'Completion record':'INS training'} | INS Market`;
 bind(page,m);bindSignOnNotification();if(page==='congratulations'&&completionCount()===9)bindCertificateDelivery().catch(()=>{if($('#certificate-email-status'))$('#certificate-email-status').textContent='Your certificate could not be prepared. Download the printable completion record or try again.';});if(scroll){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}updateTime();save();
}
function rerenderKeep(){let y=window.scrollY;render();window.scrollTo(0,y);}
function bind(page,m){
 $('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();let form=e.currentTarget;if(!form.reportValidity())return;let values=Object.fromEntries(new FormData(form));for(const [key,label] of [['name','name'],['email','email address'],['storeName','store name'],['storeNumber','store number']]){if(!String(values[key]||'').trim()){$('#profile-error').textContent=`Please enter your ${label}.`;form.elements.namedItem(key).focus();return;}}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())){$('#profile-error').textContent='Please enter a valid email address.';$('#profile-email').focus();return;}state.name=values.name.trim();state.email=values.email.trim();state.storeName=values.storeName.trim();state.store=state.storeName;state.storeNumber=values.storeNumber.trim();queueSignOnNotification();save();location.hash=completionCount()===9?'#/congratulations':'#/home';});

 $$('[data-read]').forEach(b=>b.addEventListener('click',()=>{let wasComplete=completionCount()===9;let i=Number(b.dataset.read);if(!ms(m).read.includes(i))ms(m).read.push(i);setCompleteDate();save();location.hash=!wasComplete&&completionCount()===9?'#/congratulations':b.dataset.next;}));
 $$('[data-scenario]').forEach(b=>b.addEventListener('click',()=>{let wasComplete=completionCount()===9;let i=Number(b.dataset.scenario),choice=Number(b.dataset.choice),old=ms(m).activities[i];ms(m).activities[i]={choice,done:old?.done||choice===m.activities[i].answer};setCompleteDate();save();if(!wasComplete&&completionCount()===9)location.hash='#/congratulations';else rerenderKeep();}));
 $('#lab-form')?.addEventListener('input',()=>{let form=$('#lab-form');ms(m).labValues=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox]').forEach(x=>ms(m).labValues[x.name]=x.checked);save();});
 $('#lab-form')?.addEventListener('submit',e=>{e.preventDefault();let wasComplete=completionCount()===9;let f=$('#lab-form'),data=new FormData(f),r=checkLab(m,data);ms(m).labValues=Object.fromEntries(data);f.querySelectorAll('input[type=checkbox]').forEach(x=>ms(m).labValues[x.name]=x.checked);if(r.ok)ms(m).lab=true;setCompleteDate();save();$('#lab-feedback').innerHTML=`<div class="feedback ${r.ok?'good':''}"><strong>${r.ok?'Correct. Lab completed.':'Check the working and try again.'}</strong>${esc(r.why)}</div>`;if(r.ok&&!wasComplete&&completionCount()===9){location.hash='#/congratulations';return;}if(r.ok){sidebar();let n=$('.scenario:has(#lab-form) .eyebrow');if(n)n.textContent='Practical lab · ✓ Completed';let notices=$$('.notice');let last=notices.at(-1);if(last&&practiceDone(m)){last.className='notice green';last.textContent='✓ Practice complete. Continue to the knowledge check.';}}});
 $('#reflection')?.addEventListener('input',e=>{ms(m).reflection=e.target.value;save();});
 if($('#quiz-form')){let f=$('#quiz-form');f.addEventListener('change',e=>{if(!/^q\d+$/.test(e.target.name))return;ms(m).draft[Number(e.target.name.slice(1))]=Number(e.target.value);save();if($('#answer-count'))$('#answer-count').textContent=`${Object.keys(ms(m).draft).length} of ${m.questions.length} answered`;});f.addEventListener('submit',e=>{e.preventDefault();let wasComplete=completionCount()===9;if(!ms(m).retake&&ms(m).attempts.length)return;let answers=m.questions.map((q,i)=>ms(m).draft[i]);let missing=answers.findIndex(n=>!Number.isInteger(n));if(missing>=0){$('#quiz-error').textContent=`Please answer all questions. Question ${missing+1} still needs an answer.`;$('#question-'+missing).scrollIntoView({behavior:'smooth',block:'center'});$('#question-'+missing+' input').focus({preventScroll:true});return;}let score=answers.reduce((s,n,i)=>s+(n===m.questions[i].answer),0);ms(m).attempts.push({answers,score,total:m.questions.length,date:new Date().toISOString()});ms(m).retake=false;setCompleteDate();save();if(!wasComplete&&completionCount()===9)location.hash='#/congratulations';else render();window.scrollTo(0,0);});}
 $('#retake')?.addEventListener('click',()=>{ms(m).retake=true;ms(m).draft={};save();render();window.scrollTo(0,0);});
 if(page==='library'){referenceCards();$('#library-search').addEventListener('input',referenceCards);$('#library-filter').addEventListener('change',referenceCards);}
 $('#learner-name')?.addEventListener('input',e=>{state.name=e.target.value;$('#record-name').textContent=state.name||'Learner name not entered';save();});
 $('#learner-store')?.addEventListener('input',e=>{state.store=e.target.value;$('#record-store').textContent=state.store||'Store not entered';save();});
 $('#export-earlier')?.addEventListener('click',()=>download(JSON.stringify(state.earlierEdition,null,2),'INS-Earlier-Training-Progress.json','application/json'));
 $('#export')?.addEventListener('click',()=>{save();download(JSON.stringify(state,null,2),'INS-Training-Progress.json','application/json');toast('Progress backup downloaded. Import it on your other computer.');});
 $('#results')?.addEventListener('click',()=>download(resultsText(),'INS-Training-Results.txt','text/plain'));
 $('#import')?.addEventListener('click',()=>$('#import-file').click());
 $('#import-file')?.addEventListener('change',async e=>{let file=e.target.files[0];if(!file)return;if(file.size>2000000){toast('That file is too large for a progress backup.');return;}try{let incoming=normalize(JSON.parse(await file.text()));if(!confirm('Replace the progress in this browser with the selected backup? Export the current progress first if you need it.'))return;state=incoming;setCompleteDate();save();render();toast('Progress imported.');}catch(err){toast('Could not import: '+err.message);}});
 $('#reset')?.addEventListener('click',()=>{if(!confirm('Reset this course’s readings, activities, scores, name and notes in this browser? Export a backup first if needed.'))return;state=blank();save();render();toast('This course has been reset.');});
 $('#print')?.addEventListener('click',()=>{if(completionCount()===9)window.print();});
}
function download(content,filename,type){let b=new Blob([content],{type:type+';charset=utf-8'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function resultsText(){return ['INS MARKET — OPERATIONS MANUAL TRAINING','Learning edition: 14 November 2026',`Learner: ${state.name||'Not entered'}`,`Email: ${state.email||'Not entered'}`,`Store name: ${state.storeName||'Not entered'}`,`Store number: ${state.storeNumber||'Not entered'}`,`Modules complete: ${completionCount()}/9`,`Planned duration: ${PLANNED_MINUTES} minutes`,`Recorded active study time: ${clockText()}`,`Completed at: ${state.completedAt||'Not yet complete'}`,'',...COURSE.flatMap(m=>[`${m.id}. ${m.title}`,`Reading: ${ms(m).read.length}/${m.lessons.length}; Practice: ${practiceDone(m)?'Complete':'Pending'}; Best quiz: ${ms(m).attempts.length?Math.round(best(m))+'%':'Not taken'}; Status: ${complete(m)?'Complete':'In progress'}`,`Attempts: ${ms(m).attempts.map(a=>a.score+'/'+a.total+' ('+a.date+')').join(', ')||'None'}`,`Action note: ${ms(m).reflection||'Not entered'}`,'']),'This course record does not replace INS practical certification or AGCO-approved alcohol training. Results are browser-local and not independently proctored.'].join('\n');}
document.addEventListener('click',e=>{let a=e.target.closest('a');if(a?.getAttribute('href')==='#main'){e.preventDefault();$('#main').focus();return;}if(a?.getAttribute('href')==='#course-path'){e.preventDefault();$('#course-path')?.scrollIntoView({behavior:'smooth',block:'start'});return;}let b=e.target.closest('[data-image]');if(b){$('#image-title').textContent=b.dataset.caption;$('#zoom-image').src=ASSETS[b.dataset.image];$('#zoom-image').alt=b.dataset.caption;$('#image-dialog').showModal();}});
$('#close-image').addEventListener('click',()=>$('#image-dialog').close());
$('#menu-toggle').addEventListener('click',()=>{let open=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',open);$('#backdrop').classList.toggle('open',open);$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#backdrop').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#backdrop').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#backdrop').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
['pointerdown','keydown','scroll','touchstart'].forEach(type=>document.addEventListener(type,()=>lastActivity=Date.now(),{passive:true}));
function updateTime(){let paused=state.paused||document.hidden||Date.now()-lastActivity>90000;$('#timer-value').textContent=clockText();$('#timer').classList.toggle('timer-paused',paused);$('#timer-toggle').textContent=state.paused?'Resume':'Pause';$('#timer-toggle').setAttribute('aria-label',state.paused?'Resume active study timer':'Pause active study timer');$('#timer').title=paused?'Study timer paused. Interact with the course or choose Resume.':'Active study time. Pauses when hidden, manually paused or idle for 90 seconds.';if($('#record-time'))$('#record-time').textContent=clockText();}
$('#timer-toggle').addEventListener('click',()=>{state.paused=!state.paused;lastActivity=Date.now();save();updateTime();});
let ticks=0;setInterval(()=>{let now=Date.now(),delta=Math.min((now-lastTick)/1000,2);if(!state.paused&&!document.hidden&&now-lastActivity<=90000)state.seconds+=delta;lastTick=now;updateTime();if(++ticks%10===0)save();},1000);
window.addEventListener('pagehide',save);window.addEventListener('hashchange',render);save();render();
